CREATE TABLE IF NOT EXISTS public.vice_estate_holder_balances (program text NOT NULL CHECK(program IN ('VICE','V4X')), holder_id uuid NOT NULL REFERENCES public.holders(id) ON DELETE RESTRICT, units numeric(20,0) NOT NULL DEFAULT 0 CHECK(units>=0 AND units<=7500000), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(program,holder_id)); ALTER TABLE public.vice_estate_holder_balances ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.vice_estate_holder_balances FROM PUBLIC,anon,authenticated;
